"""Rev-a MicroDuck: Feetech HL-2915 servos (3S) and the measured masses.

Installed into microduck_rl as `src/mjlab_microduck/robot/hl2915_constants.py` (source of
truth: microduck repo, `training/hl2915/`). Same joints, home pose, collisions and
observation/action layout as the stock robot — only the models' masses and the actuator
change, so a policy trained here drops into robotd unchanged.

* Models: `robot/microduck_hl2915/`, generated by `training/hl2915/make_models.py` (every
  XL330 → 28 g HL-2915, the rest scaled to the measured 850 g).
* Actuator: BAM m4 fitted on the pendulum bench (two loads, Kp 8–32, 0.53° mean error),
  `robot/microduck_hl2915/hl2915_m4.json`. `kp_fw` is the servo's live register-50 value
  that robotd writes (`[bus] position_kp`); the fit holds for register 51 (Kd) = 8 and a
  1.3 A goal-current cap, which is what robotd runs.
* Per-joint actuator spread: the stock BAM actuator scales gain and friction once per env;
  these scale them per joint, so a policy meets one hip weaker than the other. On the
  robot (2026-10-05) the left hip pitch followed its targets at 0.41 of the commanded
  amplitude where the model gives 0.65, and the right at 0.54.
* Head: the head assembly is 37% of the robot, and on rev-a the HAT, Orange Pi, fan,
  camera, ToF, microphones and speaker all sit at its front. Its CoM is moved forward by
  `HEAD_COM_FORWARD_M` — zero: the weighed head matches the model.
"""

import os
from pathlib import Path

from dataclasses import dataclass

import mujoco
import torch
from mjlab.entity import EntityArticulationInfoCfg, EntityCfg

from mjlab_microduck.actuator import hl2915 as _hl2915  # noqa: F401  registers "hl2915" with BAM
from mjlab_microduck.actuator import (
    BacklashEncoderBamActuator,
    BacklashEncoderBamActuatorCfg,
    FrictionDRBamActuator,
    FrictionDRBamActuatorCfg,
)
from mjlab_microduck.robot.microduck_constants import (
    BACKLASH_HOME_FRAME,
    FULL_COLLISION,
    HOME_FRAME,
)

_DIR: Path = Path(os.path.dirname(__file__)) / "microduck_hl2915"
HL2915_PARAMS: Path = _DIR / "hl2915_m4.json"

for _p in (_DIR / "robot_walk.xml", _DIR / "robot_allcollisions.xml",
           _DIR / "robot_walk_backlash.xml", _DIR / "robot_allcollisions_backlash.xml",
           HL2915_PARAMS):
    assert _p.exists(), f"missing: {_p} (run training/hl2915/make_models.py)"

# Register-50 Kp the policies are trained at. 16 (~2.1 N·m/rad): in simulation the stock
# policies kick at 32 once the command delay reaches 15 ms, and 16 stays stable at 25 ms
# while still having four times the stiffness the XL330 policies were trained on.
HL2915_KP = 16

_KWARGS = dict(
    json_path=str(HL2915_PARAMS),
    target_names_expr=(r"^(?!passive_).*",),
    kp_fw=float(HL2915_KP),
    # 3S: 12.6 V full (LiHV 13.3 V coming), robotd's empty threshold 9.9 V.
    vin_range=(10.0, 12.8),
    vin_drop_gain_range=(0.0, 0.15),
    vin_min=9.5,
    # Bench: current rises 2–3 ms after the write; robotd adds a 16-device read (8.8 ms)
    # and inference before it. Steps of the physics timestep.
    delay_min_lag=2,
    delay_max_lag=6,
)


def _per_joint(actuator) -> None:
    """Widen the per-env (N, 1) gain and friction scales to per joint (N, J).

    Both only ever multiply (N, J) quantities -- `kp * kp_scale` into the firmware control
    law, `friction_scale` into the friction budget -- so a per-joint tensor broadcasts the
    same way a per-env one does. The kd scale stays per env.
    """
    n, j = actuator.kp_scale.shape[0], len(actuator.ctrl_ids)

    def ones():
        return torch.ones(n, j, dtype=actuator.kp_scale.dtype, device=actuator.kp_scale.device)

    actuator.kp_scale, actuator.default_kp_scale = ones(), ones()
    actuator.friction_scale, actuator.default_friction_scale = ones(), ones()


class PerJointBamActuator(FrictionDRBamActuator):
    def initialize(self, mj_model, model, data, device) -> None:
        super().initialize(mj_model, model, data, device)
        _per_joint(self)


class PerJointBacklashBamActuator(BacklashEncoderBamActuator):
    def initialize(self, mj_model, model, data, device) -> None:
        super().initialize(mj_model, model, data, device)
        _per_joint(self)


@dataclass(kw_only=True)
class PerJointBamActuatorCfg(FrictionDRBamActuatorCfg):
    def build(self, entity, target_ids, target_names) -> PerJointBamActuator:
        return PerJointBamActuator(self, entity, target_ids, target_names)


@dataclass(kw_only=True)
class PerJointBacklashBamActuatorCfg(BacklashEncoderBamActuatorCfg):
    def build(self, entity, target_ids, target_names) -> PerJointBacklashBamActuator:
        return PerJointBacklashBamActuator(self, entity, target_ids, target_names)


hl2915_actuators = PerJointBamActuatorCfg(**_KWARGS)
hl2915_backlash_actuators = PerJointBacklashBamActuatorCfg(**_KWARGS)

# Head CoM moved forward, metres. In the head body's frame the robot's forward axis is -z
# (at the home pose), so this comes off `jaw_soft`'s ipos z. Training randomizes the head
# CoM +-10 mm around it as well. The weighed head (2026-10-07: off the head-pitch servo
# 257.1 g, CoM 36 mm up the neck and 8 mm forward of that axis) matches the model's
# 258.0 g / 36.6 mm / 8.4 mm, so this is not a correction — it is v2's training condition,
# kept so v4 differs from the v2bl that walked best only in its backlash.
HEAD_COM_FORWARD_M = 0.005


def _spec(name):
    def load() -> mujoco.MjSpec:
        spec = mujoco.MjSpec.from_file(str(_DIR / name))
        if HEAD_COM_FORWARD_M:
            head = spec.body("jaw_soft")
            ipos = list(head.ipos)
            ipos[2] -= HEAD_COM_FORWARD_M
            head.ipos = ipos
        return spec

    return load


def _robot(xml, actuators, init_state=HOME_FRAME, collisions=(FULL_COLLISION,)):
    return EntityCfg(
        spec_fn=_spec(xml),
        init_state=init_state,
        collisions=collisions,
        articulation=EntityArticulationInfoCfg(
            actuators=(actuators,),
            soft_joint_pos_limit_factor=0.9,
        ),
    )


HL2915_WALK_ROBOT_CFG = _robot("robot_walk.xml", hl2915_actuators)
HL2915_STANDUP_ROBOT_CFG = _robot("robot_allcollisions.xml", hl2915_actuators)
HL2915_WALK_BACKLASH_ROBOT_CFG = _robot("robot_walk_backlash.xml", hl2915_backlash_actuators,
                                        BACKLASH_HOME_FRAME)
HL2915_BACKLASH_ROBOT_CFG = _robot("robot_allcollisions_backlash.xml", hl2915_backlash_actuators,
                                   BACKLASH_HOME_FRAME)
